UPDATE UNIFIED_PLAYER_TABLE SET FANTRAX_ID = '*06mmr*' WHERE MASTER_PLAYER_ID = 5062 AND FANTRAX_ID IS NULL;  -- Zyon Pullin  <- Pullin, Zyon (MIN)

-- Expect: populated count rises by the number of statements above.
SELECT COUNT(*) AS fantrax_ids_populated FROM UNIFIED_PLAYER_TABLE WHERE FANTRAX_ID IS NOT NULL;

-- Expect: zero rows. A Fantrax id on two rows means the roster lookup answers with whichever
-- it reaches first.
SELECT FANTRAX_ID, COUNT(*) AS rows_sharing_it FROM UNIFIED_PLAYER_TABLE
 WHERE FANTRAX_ID IS NOT NULL GROUP BY FANTRAX_ID HAVING COUNT(*) > 1;

